opng_strcasecmp(const char *str1, const char *str2)
{
    int ch1, ch2;

    /* Perform a case-insensitive string comparison. */
    for ( ; ; )
    {
        ch1 = tolower(*str1++);
        ch2 = tolower(*str2++);
        if (ch1 != ch2)
            return ch1 - ch2;
        if (ch1 == 0)
            return 0;
    }
    /* FIXME: This function is not MBCS-aware. */
}

int opng_strcasecmp_valid(int8_t left[16], int8_t right[16]) { left[15]=0; right[15]=0; return opng_strcasecmp((char *)left,(char *)right); }
